type RawCardTuple = [
  id: string,
  phraseEn: string,
  phraseRu: string,
  phoneticRu: string,
  contextRu: string,
];

function buildLevelCards(
  dictLevel: number,
  topicRu: string,
  items: RawCardTuple[]
): FlashcardItem[] {
  const now = Date.now();
  return items.map(([id, phraseEn, phraseRu, phoneticRu, contextRu]) => ({
    id,
    dictLevel,
    topicRu,
    phraseEn,
    phraseRu,
    phoneticRu,
    contextRu,
    box: 1,
    nextReview: now,
    timesReviewed: 0,
  }));
}

